import { Injectable, Inject } from '@nestjs/common';
import { sql } from 'drizzle-orm';
import { ISqlAdapter } from '../interfaces/db-adapter.interface.js';

@Injectable()
export class DrizzleSqlAdapter<TClient = unknown> implements ISqlAdapter<TClient> {
  constructor(
    @Inject('DRIZZLE_CLIENT') private readonly db: TClient
  ) {}

  async query<T = unknown>(queryString: string, _params: unknown[] = []): Promise<T[]> {
    const result = await (this.db as any).execute(sql.raw(queryString));
    return (result.rows || result) as T[];
  }

  async execute(queryString: string, _params: unknown[] = []): Promise<unknown> {
    return (this.db as any).execute(sql.raw(queryString));
  }

  getClient(): TClient {
    return this.db;
  }

  async onModuleDestroy(): Promise<void> {
    const client = (this.db as any).$client;
    if (typeof client?.end === 'function') {
      await client.end();
    } else if (typeof client?.close === 'function') {
      await client.close();
    }
  }
}

import { DynamicModule, Module, Global, Provider } from '@nestjs/common';
import { DbService } from './db.service.js';


import { DrizzleSqlAdapter } from './adapters/sql/drizzle-sql.adapter.js';
import * as schema from './orm/drizzle/schema.js';
import { drizzle } from 'drizzle-orm/better-sqlite3';
import Database from 'better-sqlite3';



export interface DbModuleOptions {
  sqlitePath?: string;
}

@Global()
@Module({})
export class DbModule {
  static forRoot(options: DbModuleOptions): DynamicModule {
    const initialProviders: Provider[] = [DbService];
    const providers = initialProviders;


    providers.push({
      provide: 'DRIZZLE_CLIENT',
      useFactory: () => {
        const client = new Database(options.sqlitePath || ':memory:');
        return drizzle({ client, schema });
              },
    }, { provide: 'SQL_ADAPTER', useClass: DrizzleSqlAdapter });



    return {
      exports: [DbService],
      module: DbModule,
      providers,
    };
  }
}

import { Injectable, Inject } from '@nestjs/common';
